-- =====================================================================
-- DATOS FICTICIOS PARA DEMOSTRACIÓN. Ninguna persona es real.
-- Correr después de la migración, como dueño de la base (editor SQL de Supabase).
-- Para borrarlos: ver supabase/borrar_demo.sql
-- =====================================================================
begin;
select v.comunidad_id, v.morador_id, v.asamblea_id,
       case when v.estado='ausente' and v.tipo_evento='faena' then 'faena' when v.estado='ausente' then 'inasistencia' else v.estado end,
       case when v.estado='ausente' then a.multa_falta else a.multa_sin_salida end,
       v.asamblea || ' del ' || to_char(v.fecha,'DD/MM/YYYY'), a.cerrada_en + interval '1 day'
  from public.v_asistencia v join public.asambleas a on a.id=v.asamblea_id
  join public.moradores m on m.id=v.morador_id
 where a.id like 'demo-%' and m.obligado and v.estado in ('ausente','sin_salida','sin_entrada')
   and coalesce(case when v.estado='ausente' then a.multa_falta else a.multa_sin_salida end,0) > 0
on conflict do nothing;
-- Pagos: ~70 % de las multas anteriores a octubre, con recibo
with p as (select id, row_number() over (order by creada, id) n from public.multas
            where asamblea_id like 'demo-%' and creada < '2026-10-01' and abs(hashtext(id::text)) % 10 < 7)
update public.multas mu set estado='pagada', pagada_en = mu.creada + interval '9 days', recibo = 'R-' || lpad(p.n::text, 4, '0')
  from p where p.id = mu.id;
update public.multas set estado='condonada', nota='Condonada por enfermedad (acuerdo de asamblea)'
 where id = (select id from public.multas where asamblea_id like 'demo-%' and estado='pendiente' order by creada, id limit 1);
commit;
